export function background(ctx,arena){const colors=arena==='space'?['#100c29','#33375d','#495368']:arena==='temple'?['#67a8c6','#b4d7d3','#758b83']:['#69b6b4','#acd1a0','#487d65'];const g=ctx.createLinearGradient(0,0,0,540);g.addColorStop(0,colors[0]);g.addColorStop(1,colors[1]);ctx.fillStyle=g;ctx.fillRect(0,0,960,540);if(arena==='space'){ctx.fillStyle='#dce4ef';for(let i=0;i<75;i++){const x=(i*137)%960,y=(i*73)%340;ctx.globalAlpha=.25+(i%5)*.12;ctx.fillRect(x,y,i%3===0?2:1,1)}ctx.globalAlpha=1;ctx.fillStyle='#6964a0';ctx.beginPath();ctx.arc(740,170,65,0,Math.PI*2);ctx.fill()}else{ctx.fillStyle=arena==='namek'?'#e2d39e':'#e8d1a4';ctx.beginPath();ctx.arc(750,160,45,0,Math.PI*2);ctx.fill();for(let layer=0;layer<3;layer++){ctx.fillStyle=['#648b8a','#4f7873','#3e6662'][layer];ctx.beginPath();ctx.moveTo(0,440);for(let x=0;x<=1000;x+=25)ctx.lineTo(x,340-layer*30-Math.sin(x*.009+layer*3)*40-Math.sin(x*.021+layer)*18);ctx.lineTo(960,540);ctx.closePath();ctx.fill()}if(arena==='namek'){for(const x of [100,280,830]){ctx.fillStyle='#4d6a47';ctx.fillRect(x,265,7,130);ctx.fillStyle='#92c085';ctx.beginPath();ctx.ellipse(x+3,264,42,15,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#aecf8d';ctx.fillRect(x-25,258,50,4)}}else{for(const x of [150,810]){ctx.fillStyle='#536565';ctx.fillRect(x-15,240,30,150);ctx.fillStyle='#877f6e';ctx.fillRect(x-22,232,44,12)}ctx.fillStyle='#8c7063';ctx.fillRect(330,280,300,100);ctx.fillStyle='#4a5860';ctx.beginPath();ctx.moveTo(290,282);ctx.lineTo(480,220);ctx.lineTo(670,282);ctx.closePath();ctx.fill()}}
ctx.fillStyle=colors[2];ctx.fillRect(0,426,960,114);ctx.fillStyle=arena==='temple'?'#b3b0a0':'#98ad7c';ctx.fillRect(0,426,960,9);ctx.strokeStyle=arena==='temple'?'#717b79':'#5c8060';ctx.lineWidth=1;for(let i=0;i<20;i++){const x=i*55;ctx.beginPath();ctx.moveTo(x,437);ctx.lineTo(x-50,540);ctx.stroke()}ctx.fillStyle='#ffffff13';ctx.fillRect(0,437,960,2)}
